D("populate",{etymology:E("From Latin populare ‘people, inhabit’, from populus ‘people’; the English verb means live in a place or cause it to be filled with inhabitants.",null,"populus",null,"Etymonline, populate (https://www.etymonline.com/word/populate)."),contexts:[C("populate.s1","社會","New families began to populate the valley after the rail line connected it to the coast.","鐵路連接山谷與海岸後，新家庭開始在谷地定居。","To populate a place is to live there or fill it with people.","Populate takes valley as object; after introduces the change that enabled settlement.","Families move into the valley and make it inhabited.")],mistakes:[M("meaning","Workers populated the empty village by forcing every resident to leave and keeping the houses vacant.","Workers populated the empty village by helping new families settle there.","Populate means inhabit or fill a place with people, not empty it.")],quiz:[Q("populate.q1","populate.s1","meaning","To populate an island is to ___.",["live there or fill it with inhabitants","remove every resident","measure its coastline"],"live there or fill it with inhabitants","The verb concerns inhabiting a place.","meaning"),Q("populate.q2","populate.s1","context","Which event would populate a new settlement?",["Families move in and establish homes.","Residents abandon the town.","A storm removes all buildings."],"Families move in and establish homes.","New residents make the area inhabited.","context"),Q("populate.q3","populate.s1","word-choice","New plants quickly ____ the meadow after the fire.",["populate","pore","ponder"],"populate","The plants spread through and fill the meadow.","word-choice"),Q("populate.q4","populate.s1","meaning","What happens when a region is populated?",["People live in it.","It becomes entirely underwater.","It is divided into school periods."],"People live in it.","Populate means inhabit or fill a place with people.","meaning")]});
